{
  "event": {
    "title": "New Year Concert",
    "description": "A brand new year concert in Addis Ababa",
    "visibility": "public",
    "timezone": "Africa/Addis_Ababa",
    "currency": "ETB",
    "organization_id": "{{organizationId}}",
    "category_ids": [
      "{{categoryId}}"
    ]
  }
}

{
  "name": "General Admission Ticket",
  "type": "ticket",
  "description": "Standard entry to the event",
  "allow_custom_price": false,
  "sales_start_at": "2026-08-01T00:00:00Z",
  "sales_end_at": "2026-09-01T00:00:00Z",
  "min_per_order": 1,
  "max_per_order": 10,
  "sort_order": 1,
  "ticket_type_attributes": {
    "approval_mode": "automatic",
    "audience": "public",
    "date_selection": "fixed",
    "admissions_per_unit": 1
  },
  "price_attributes": {
    "type": "base",
    "currency": "ETB",
    "amount_minor": 50000,
    "active_from": "2026-08-01T00:00:00Z"
  },
  "inventory_configuration": {
    "mode": "per_date",
    "dates": [
      {
        "event_date_id": "{{eventDateId}}",
        "capacity": 5000
      }
    ]
  }
}

{
  "version": 1,
  "questions": [
    {
      "key": "full_name",
      "type": "short_text",
      "response_scope": "registration",
      "sensitivity": "standard",
      "label": "Full name",
      "help_text": "Enter the attendee's full name.",
      "required": true,
      "position": 0,
      "options": [],
      "validation_rules": {
        "min_length": 2
      }
    }
  ]
}

{
  "consent_document": {
    "name": "Terms of Entry",
    "type": "terms",
    "title": "Attendee Terms",
    "body": "Enter the terms text here."
  }
}

